import re,xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
ss=[ ''.join(t.text or '' for t in si.iter('{%s}t'%ns['m'])) for si in ET.parse('xl/sharedStrings.xml').getroot()]
def sheet(f):
    rows={}
    for r in ET.parse(f).getroot().find('m:sheetData',ns):
        for c in r:
            ref=c.get('r'); t=c.get('t')
            v=c.find('m:v',ns); fm=c.find('m:f',ns)
            val=None
            if v is not None:
                val=ss[int(v.text)] if t=='s' else v.text
            rows[ref]=(val, fm.text if fm is not None else None)
    return rows
cs=sheet('xl/worksheets/sheet3.xml')
for k in sorted(cs, key=lambda x:(int(re.sub(r'\D','',x)), re.sub(r'\d','',x))):
    print(k, cs[k])
EOF

